<template>
  <div class="creative-page">
    <header><div><strong>白同学短剧助手</strong><span>创作 Skill 规则</span></div><el-button @click="router.back()">返回</el-button></header>
    <main>
      <section class="hero"><div><p class="eyebrow">CREATIVE SKILLS</p><h1>故事与资产提示词</h1><p>分别为故事剧本、人物图、场景图和道具图接入你的 Skill。人物、场景、道具提取仍使用平台内置规则，确保数据结构稳定。</p></div><label class="upload"><input type="file" accept=".zip,.json,.md" @change="importFile" :disabled="busy"><span>{{ busy ? '正在导入…' : '导入创作 Skill' }}</span></label></section>
      <section class="bindings"><article><div class="binding-head"><div><small>STORY GENERATION</small><h2>故事 / 剧本生成</h2></div><el-tag v-if="settings.story_pack_id" type="success">已启用</el-tag></div><p>{{ settings.story_name }}<em v-if="settings.story_version"> v{{ settings.story_version }}</em></p><el-select v-model="settings.story_pack_id" clearable placeholder="平台内置故事规则" @change="saveSettings"><el-option v-for="p in storyPacks" :key="p.id" :label="`${p.name} v${p.version}`" :value="p.id" /></el-select></article><article><div class="binding-head"><div><small>ASSET IMAGE PROMPTS</small><h2>人物 / 场景 / 道具图</h2></div><el-tag v-if="settings.asset_pack_id" type="success">已启用</el-tag></div><p>{{ settings.asset_name }}<em v-if="settings.asset_version"> v{{ settings.asset_version }}</em></p><el-select v-model="settings.asset_pack_id" clearable placeholder="平台内置资产规则" @change="saveSettings"><el-option v-for="p in assetPacks" :key="p.id" :label="`${p.name} v${p.version}`" :value="p.id" /></el-select></article></section>
      <section class="grid"><article v-for="pack in packs" :key="pack.id" class="pack"><div class="pack-top"><div><h3>{{ pack.name }}</h3><small>{{ pack.kind === 'story' ? '故事剧本 Skill' : '人物 / 场景 / 道具资产 Skill' }} · v{{ pack.version }}</small></div><el-tag size="small">{{ pack.active_paths?.length || 0 }} 个生效文件</el-tag></div><p>{{ pack.source }}</p><div class="files">{{ (pack.active_paths || []).slice(0, 5).join(' · ') }}</div><div class="actions"><el-button size="small" @click="choose(pack)">{{ isSelected(pack) ? '当前已用' : '用于本项目' }}</el-button><a :href="creativeSkillRulesAPI.exportUrl(pack.id)" download>导出 JSON</a></div></article><div v-if="!packs.length" class="empty">还没有创作 Skill。请导入 ZIP、JSON 或 SKILL.md。</div></section>
      <p class="note">平台会把自定义 Skill 放在对应阶段的内置规则前面，并追加格式适配约定。已保存的提取结果、图片接口和素材库字段不会被改写。</p>
    </main>
  </div>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { creativeSkillRulesAPI } from '@/api/creativeSkillRules'
const router = useRouter(); const route = useRoute(); const packs = ref([]); const busy = ref(false)
const settings = ref({ story_pack_id: null, asset_pack_id: null, story_name: '平台内置故事规则', asset_name: '平台内置资产规则' })
const storyPacks = computed(() => packs.value.filter(p => p.kind === 'story')); const assetPacks = computed(() => packs.value.filter(p => p.kind === 'asset'))
async function load() { const d = await creativeSkillRulesAPI.list(); packs.value = d?.packs || []; if (route.params.id) settings.value = await creativeSkillRulesAPI.getProject(route.params.id) }
async function importFile(e) { const file = e.target.files?.[0]; if (!file) return; busy.value = true; try { const bytes = await file.arrayBuffer(); let binary = ''; const data = new Uint8Array(bytes); for (let i = 0; i < data.length; i += 0x8000) binary += String.fromCharCode(...data.subarray(i, i + 0x8000)); const out = await creativeSkillRulesAPI.importBase64(file.name, btoa(binary)); ElMessage.success(`已导入 ${out.pack.name} v${out.pack.version}`); await load() } catch (e) { ElMessage.error(e.message || '导入失败') } finally { busy.value = false; e.target.value = '' } }
async function saveSettings() { if (!route.params.id) return; settings.value = await creativeSkillRulesAPI.setProject(route.params.id, { story_pack_id: settings.value.story_pack_id, asset_pack_id: settings.value.asset_pack_id }); ElMessage.success('创作 Skill 配置已保存') }
async function choose(pack) { if (!route.params.id) return ElMessage.warning('请从具体项目进入创作 Skill 设置'); if (pack.kind === 'story') settings.value.story_pack_id = pack.id; else settings.value.asset_pack_id = pack.id; await saveSettings() }
function isSelected(pack) { return pack.kind === 'story' ? settings.value.story_pack_id === pack.id : settings.value.asset_pack_id === pack.id }
onMounted(load)
</script>
